<script setup lang="ts">
import { computed, reactive, ref, shallowRef, watch } from 'vue'
import { onLoad } from '@dcloudio/uni-app'
import {
  type InvoiceCreate,
  invoiceCreate,
  type InvoiceLineInput,
  type ValidationIssue,
} from '@qiwu/shared'
import { invoiceApi } from '@/api/demo/invoice'
import QwDictSelect from '@/core/components/QwDictSelect.vue'
import QwEmpty from '@/core/components/QwEmpty.vue'
import { fillForm, type Form, numOf, useDatePicker } from '@/core/crud'
import { formatTime } from '@/core/format'
import { fieldErrors, t } from '@/core/i18n'
import { ApiError, errorText } from '@/core/request'

/**
 * Add / edit page of the invoice list (mobile, generated): `?id=` edits that row, else it
 * adds one. The rules: the shared `invoiceCreate`
 * (the server checks again). The save button shows loading and is disabled while pending.
 */
const id = ref(0)
const ready = ref(false)
const error = ref('')
const submitting = ref(false)
const form = reactive<Form<InvoiceCreate>>({
  invoiceNo: '',
  buyer: '',
  total: 0,
  issuedAt: null,
  state: 'draft',
  lines: [],
})
const issues = shallowRef<ValidationIssue[]>([])
const errors = computed(() => fieldErrors(invoiceCreate, issues.value))
// once shown, the messages follow the input
watch(form, () => {
  if (issues.value.length) issues.value = invoiceCreate.safeParse(form).error?.issues ?? []
})
const { picking, value: pickedAt, open: pickDate, pick, closed } = useDatePicker()
const newInvoiceLine = (): Form<InvoiceLineInput> => ({ item: '', qty: 1, unitPrice: 0 })

onLoad(async (query) => {
  id.value = Number(query?.id) || 0
  const name = t('demo.invoice.entity')
  uni.setNavigationBarTitle({
    title: t(id.value ? 'crud.title.edit' : 'crud.title.create', { name }),
  })
  if (id.value)
    try {
      fillForm(form, await invoiceApi.get(id.value))
    } catch (e) {
      return void (error.value = errorText(e))
    }
  ready.value = true
})

async function submit() {
  if (submitting.value) return
  const parsed = invoiceCreate.safeParse(form)
  issues.value = parsed.error?.issues ?? []
  if (!parsed.success) return
  submitting.value = true
  error.value = ''
  try {
    if (id.value) await invoiceApi.update(id.value, parsed.data)
    else await invoiceApi.create(parsed.data)
    uni.showToast({ title: t(id.value ? 'crud.msg.updated' : 'crud.msg.created'), icon: 'none' })
    uni.navigateBack()
  } catch (e) {
    // a 400 (the rules), a 404 (gone, out of scope) belongs here; the request layer toasts the rest (409: a
    // unique value taken)
    if (e instanceof ApiError && (e.status === 400 || e.status === 404)) error.value = e.message
  } finally {
    submitting.value = false
  }
}
</script>
